std::vector<array> ArcTan2::vjp(
    const std::vector<array>& primals,
    const std::vector<array>& cotangents,
    const std::vector<int>& argnums,
    const std::vector<array>&) {
  assert(primals.size() == 2);
  assert(cotangents.size() == 1);

  const auto& s = stream();
  const array& x1 = primals[0];
  const array& x2 = primals[1];
  const array& dy = cotangents[0];

  std::vector<array> grads;
  array dy_over_x1_x2_squared =
      divide(dy, add(square(x1, s), square(x2, s)), s);

  for (auto arg : argnums) {
    if (arg == 0) {
      grads.emplace_back(multiply(x2, dy_over_x1_x2_squared, s));
    } else {
      grads.emplace_back(multiply(negative(x1, s), dy_over_x1_x2_squared, s));
    }
  }

  return grads;
}

std::vector<array> ArcTan2::jvp(
    const std::vector<array>& primals,
    const std::vector<array>& tangents,
    const std::vector<int>& argnums) {
  assert(primals.size() == 2);
  assert(tangents.size() == argnums.size());

  const auto& s = stream();
  const array& x1 = primals[0];
  const array& x2 = primals[1];

  auto numerator = [&]() {
    if (argnums.size() == 2) {
      return subtract(
          multiply(x2, tangents[0], s), multiply(x1, tangents[1], s), s);
    } else if (argnums[0] == 0) {
      return multiply(x2, tangents[0], s);
    } else {
      return negative(multiply(x1, tangents[0], s), s);
    }
  }();
  return {divide(numerator, add(square(x1, s), square(x2, s), s), s)};
}

